{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required field")
    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list):
        raise ValueError("segments must be a list")
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise ValueError("budget must be an integer")
    allocations = []
    names = set()
    total_minimum = 0
    total_capacity = 0
    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("each segment must be an object")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError("missing segment field")
        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]
        if not isinstance(name, str):
            raise ValueError("name must be a string")
        if name in names:
            raise ValueError("segment names must be unique")
        names.add(name)
        for value in (importance, minimum, capacity):
            if isinstance(value, bool) or not isinstance(value, int):
                raise ValueError("segment quantities must be integers")
        if importance < 0 or minimum < 0 or capacity < minimum:
            raise ValueError("invalid segment bounds")
        allocations.append(minimum)
        total_minimum += minimum
        total_capacity += capacity
    if budget < total_minimum or budget > total_capacity:
        raise ValueError("infeasible budget")
    remaining = budget - total_minimum
    while remaining:
        best = -1
        for index, segment in enumerate(segments):
            position = allocations[index] + 1
            if allocations[index] >= segment["capacity"]:
                continue
            if best < 0 or segment["importance"] * (allocations[best] + 1) > segments[best]["importance"] * position:
                best = index
        if best < 0:
            raise ValueError("infeasible budget")
        allocations[best] += 1
        remaining -= 1
    by_name = {segment["name"]: allocations[index] for index, segment in enumerate(segments)}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}"}
